let screen:ReturnType<typeof ui>;afterEach(async()=>{await screen?.close();vi.useRealTimers();});
test('AGW-06 opening another campaign leaves the old notification target and shows the selected review',async()=>{
 screen=ui();const f=fixture(),first=launchReview(),second=launchReview();second.campaign.id='campaign2';second.campaign.draft.name='Segunda campanha';second.proposal.id='proposal2';second.proposal.campaignId='campaign2';
 f.props.overview.campaigns=[first.campaign,second.campaign];f.props.overview.proposals=[first.proposal,second.proposal];f.approval.review.mockImplementation(async(id:string)=>id==='campaign2'?second:first);
 const target={merchantId:'a',campaignId:'campaign1',proposalId:'proposal1'};
 await screen.render(<MetaAdsAssistant {...f.props} reviewTarget={target}/>);expect(screen.container.querySelector('.mga-launch')!.textContent).toContain(first.campaign.draft.name);
 await screen.render(<MetaAdsAssistant {...f.props} reviewTarget={target} selectedCampaignId="campaign2"/>);
 expect(screen.container.querySelector('.mga-launch')!.textContent).toContain('Segunda campanha');
 expect(f.approval.review).toHaveBeenLastCalledWith('campaign2',undefined,expect.any(AbortSignal));expect(f.approval.approveLaunch).not.toHaveBeenCalled();
});
const turn=(patch:Partial<AssistantTurn>={}):AssistantTurn=>({id:'t',threadId:'h',ordinal:1,status:'completed',message:'Ajuda',reply:'Resposta persistida',references:[],artifacts:[],error:null,createdAt:'2026-11-16T12:00:00Z',updatedAt:'2026-11-16T12:00:00Z',...patch});
test('FR-04 launch proposal review moves focus out of the hidden chat to the canonical review',async()=>{screen=ui();const value=launchReview(),f=fixture(thread([turn({artifacts:[{type:'proposal',proposal:value.proposal,execution:null}]})]));f.approval.preparation.mockResolvedValue({campaignDigest:'a'.repeat(64),preparations:[preparation('review_ready')]} as never);await screen.render(<MetaAdsAssistant {...f.props}/>);const trigger=Array.from(screen.container.querySelectorAll('button')).find(button=>button.textContent==='Revisar campanha')!;trigger.focus();expect(document.activeElement).toBe(trigger);await screen.click('Revisar campanha');await new Promise(resolve=>setTimeout(resolve,15));expect(screen.container.querySelector<HTMLElement>('.chat-dock-panel')!.hidden).toBe(true);expect(document.activeElement).toBe(screen.container.querySelector('[data-campaign-review]'));expect(screen.container.querySelector('.mga-launch')?.textContent).toContain(value.campaign.draft.primaryText);expect(f.approval.approveLaunch).not.toHaveBeenCalled();});
const thread=(turns:AssistantTurn[]=[]):AssistantThread=>({id:'h',context:{id:'meta-ads',label:'Anúncios com IA',capabilities:[]},revision:turns.length,campaign:null,turns,nextCursor:null,updatedAt:'2026-11-16T12:00:00Z'});
const manual={mode:'manual' as const,policy:null,committedCents:0,availableCents:null,version:0};
const preparation=(status='queued',missing:string[]=[])=>({id:'prep1',campaignId:'campaign1',intentDigest:'a'.repeat(64),status,requestedImages:2,generationId:'g1',proposalId:status==='review_ready'?'proposal1':null,missing,error:missing[0]??null,createdAt:'2026-11-17T12:00:00Z',updatedAt:'2026-11-17T12:00:00Z'});
const policyReview:MetaAdsAutomationReview={accountId:'123',connectionEpoch:1,version:1,digest:'policy-digest',warnings:[],scope:{variantIds:['variant1'],campaignIds:[],allowNewCampaigns:true,destination:'store',priority:'paid_sales',country:'BR',actions:['pause']},limits:{currency:'BRL',cadence:'lifetime',campaignCeilingCents:10000,storeCeilingCents:20000,startsAt:'2026-11-16T12:00:00Z',endsAt:'2026-11-23T12:00:00Z'}};
const automatic={...manual,mode:'automatic' as const,version:1,availableCents:20000,policy:{...policyReview,id:'p',acceptedBy:'owner',acceptedAt:'2026-11-16T12:00:00Z',revokedAt:null}};

test('ACJ-02 policy planning identifies its context and reviews canonical product names without a campaign',async()=>{
 screen=ui();const history=thread([turn({reply:'O retorno, também chamado ROAS, compara vendas e investimento.',artifacts:[{type:'automation_review',review:policyReview}]})]);history.campaign={campaignId:null,draft:{},awaitingFields:[],planningKind:'automation',automationBriefing:{scope:policyReview.scope,limits:policyReview.limits,selection:{productOptions:[{variantId:'variant1',name:'Bolsa Aurora'}]}}};const f=fixture(history);await screen.render(<MetaAdsAssistant {...f.props}/>);
 expect(screen.container.querySelector('.mga-chat-context')?.textContent).toContain('Modo autônomo');expect(screen.container.querySelector('.mga-chat-context')?.textContent).not.toContain('Campanha da loja');expect(screen.container.querySelector('.mga-term-help')).toBeNull();await screen.click('Configurações');await screen.click('Autonomia');const policy=screen.container.querySelector('[aria-label="Autonomia dos anúncios"]')!;expect(policy.textContent).toContain('Bolsa Aurora');expect(policy.textContent).not.toContain('variant1');expect(policy.textContent).toContain('Campanhas atuais e futuras');expect(f.client.acceptAutomation).not.toHaveBeenCalled();
});
function fixture(history=thread()){
  const client={dispose:vi.fn(),thread:vi.fn().mockResolvedValue(history),page:vi.fn().mockResolvedValue(history),submit:vi.fn(async(_context:string,_id:string,input:AssistantTurnInput)=>({turn:turn({status:'queued',reply:null,message:input.message}),revision:1,replayed:false})),source:vi.fn().mockResolvedValue({id:'funds',version:'1',title:'Como financiar anúncios',url:'/?tab=meta-ads-agent&help=funds',reviewedAt:'2026-11-16',sections:[{id:'one',content:'A verba é paga diretamente à Meta.'}],externalSources:[{title:'Documentação da Meta',url:'https://developers.facebook.com/docs/graph-api/reference/ad-account/'}]}),funding:vi.fn().mockResolvedValue({snapshot:null,status:'unknown',message:'Sem leitura financeira',nextSteps:[],error:null}),refreshFunding:vi.fn().mockResolvedValue({snapshot:null,status:'unknown',message:'Sem leitura financeira',nextSteps:[],error:null}),automation:vi.fn().mockResolvedValue(manual),acceptAutomation:vi.fn().mockResolvedValue(automatic),manual:vi.fn().mockResolvedValue({...manual,version:2}),reports:vi.fn().mockResolvedValue({reports:[]}),report:vi.fn()};
  const approval={dispose:vi.fn(),contact:vi.fn().mockResolvedValue({phoneNumber:null,consented:false,version:0}),saveContact:vi.fn(),preparation:vi.fn().mockResolvedValue({campaignDigest:'a'.repeat(64),preparations:[]}),prepare:vi.fn(),review:vi.fn().mockResolvedValue(launchReview()),approveLaunch:vi.fn()};
  return {client,approval,props:{merchantId:'a',apiBaseUrl:'https://api.example.test',overview:overview(),api:{preparationLimits:vi.fn().mockResolvedValue({limits:{dailyNewProposals:1,maximumPendingProposals:3,version:0,updatedAt:null},effectiveDailyLimit:1,effectivePendingLimit:3,planCampaignCapacity:5,usedToday:0,pending:0,availableToday:1,availablePendingSlots:3,localDay:'2026-11-22',blockedReason:null}),savePreparationLimits:vi.fn()} as unknown as MetaAdsAgentApi,client:client as unknown as MerchantAssistantApi,approvalClient:approval as unknown as CampaignApprovalApi,onUpdated:vi.fn().mockResolvedValue(undefined),pollMs:60000}};
}

function campaignFixture(status='queued',missing:string[]=[]){const h=thread();h.campaign={campaignId:'campaign1',draft:campaign().draft,awaitingFields:[]};const f=fixture(h);f.props.overview.campaigns=[campaign()];f.approval.preparation.mockResolvedValue({campaignDigest:'a'.repeat(64),preparations:[preparation(status,missing)]} as never);return f;}
test('FR-04 Ver anúncio closes chat, focuses the full photo review and leaves approval explicit',async()=>{
 screen=ui();const f=campaignFixture('blocked',['meta_whatsapp_not_linked']),c=f.props.overview.campaigns[0];f.client.thread.mockResolvedValue(thread([turn({artifacts:[{type:'campaign',campaign:c}]})]));await screen.render(<MetaAdsAssistant {...f.props}/>);await screen.click('Ver anúncio');await new Promise(resolve=>setTimeout(resolve,15));const anchor=screen.container.querySelector<HTMLElement>('[data-campaign-review]')!;expect(document.activeElement).toBe(anchor);expect(screen.container.querySelector<HTMLElement>('.chat-dock-panel')!.hidden).toBe(true);expect(anchor.querySelector('img')?.getAttribute('src')).toBe(c.products[0].imageUrl);expect(anchor.textContent).toContain(c.draft.primaryText);expect(Array.from(anchor.querySelectorAll('button')).find(button=>button.textContent==='Aprovar e publicar')?.disabled).toBe(true);expect(f.approval.approveLaunch).not.toHaveBeenCalled();
});

test('workspace chat delegates campaign review to one focused surface while retaining its conversation',async()=>{screen=ui();const f=campaignFixture(),c=f.props.overview.campaigns[0],open=vi.fn();f.client.thread.mockResolvedValue(thread([turn({reply:'Seu anúncio está pronto para conferir.',artifacts:[{type:'campaign',campaign:c}]})]));await screen.render(<MetaAdsAssistant {...f.props} onOpenCampaign={open}><p>Lista compacta</p></MetaAdsAssistant>);await screen.click('Abrir assistente');await screen.click('Ver anúncio');expect(open).toHaveBeenCalledWith({campaignId:c.id,source:'chat'});expect((screen.container.querySelector('.chat-dock-panel') as HTMLElement).hidden).toBe(true);expect(screen.container.textContent).toContain('Seu anúncio está pronto para conferir.');expect(screen.container.querySelector('[data-campaign-review]')).toBeNull();expect(f.approval.approveLaunch).not.toHaveBeenCalled();});
test('workspace notification delegates its exact campaign and proposal without an inline duplicate',async()=>{screen=ui();const f=campaignFixture(),open=vi.fn();await screen.render(<MetaAdsAssistant {...f.props} onOpenCampaign={open} reviewTarget={{merchantId:'a',campaignId:'campaign1',proposalId:'proposal1'}}/>);expect(open).toHaveBeenCalledTimes(1);expect(open).toHaveBeenCalledWith({campaignId:'campaign1',proposalId:'proposal1',source:'notification'});expect(screen.container.querySelector('[data-campaign-review]')).toBeNull();expect(f.approval.approveLaunch).not.toHaveBeenCalled();});
test('workspace rejects a foreign notification before delegating any campaign selection',async()=>{screen=ui();const f=fixture(),open=vi.fn();await screen.render(<MetaAdsAssistant {...f.props} onOpenCampaign={open} reviewTarget={{merchantId:'another-store',campaignId:'campaign1',proposalId:'proposal1'}}/>);expect(open).not.toHaveBeenCalled();expect(screen.container.textContent).toContain('Esta revisão pertence a outra loja.');expect(f.approval.review).not.toHaveBeenCalled();});
